  for (let t = 0; t < N; t++) {
    const rnd = `() => { const seed = ${t * 7919 + 13}; let s = seed; const rnd = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
      document.querySelectorAll('.disc-list').forEach(ul => { const items = Array.from(ul.children);
        for (let i = items.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [items[i], items[j]] = [items[j], items[i]]; }
        items.forEach(li => ul.appendChild(li)); }); }`;
    await orig.evaluate(rnd); await copy.evaluate(rnd);
    await orig.evaluate(() => document.querySelector('[data-disc-finish]').click());
    await sleep(400);
    const tk = await orig.evaluate(() => sessionStorage.getItem('disc_result_token_v1'));
    await copy.evaluate(() => document.getElementById('btnFinish').click());
    const sh = await copy.evaluate(() => document.getElementById('resultLine').textContent);
    const og = fmt(decrypt(tk).score);
    if (og === sh) ok++; else console.log('MISMATCH', t, og, sh);
  }
  console.log(`random permutations matched: ${ok}/${N}`);
  await browser.close();
})().catch(e => { console.error('FAIL', e); process.exit(1); });
